  "I2": "def en_iyi_sira(isler):
    n = len(isler)
    dp = [float('inf')] * (1 << n)
    dp[0] = 0

    # Her maske için toplam süreyi önceden hesapla
    times = [0] * (1 << n)
    for mask in range(1 << n):
        for i in range(n):
            if (mask >> i) & 1:
                times[mask] += isler[i][0]

    # DP ile minimum maliyeti bul
    for mask in range(1 << n):
        if dp[mask] == float('inf'):
            continue

        current_time = times[mask]
        for i in range(n):
            if not ((mask >> i) & 1):
                sure, son_tarih, agirlik = isler[i]
                bitis = current_time + sure
                gecikme = max(0, bitis - son_tarih)
                maliyet = agirlik * gecikme

                new_mask = mask | (1 << i)
                if dp[new_mask] > dp[mask] + maliyet:
                    dp[new_mask] = dp[mask] + maliyet

    return int(dp[(1 << n) - 1])"
}

